INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (1, 'D173-A1-01', 'ብትን ጨርቅ ከካኪ የተሰራ', 'Khaki fabric, cut length (100% cotton khaki)', 'clothing', 'metre', false, true, 'fabric', 'Annex 1 (አባሪ 1) #1', 'Art. 2(5): khaki = 100% cotton khaki twill. Art. 4(1): used for coveralls, full work coat, ¾ coat and apron. Price-list quantity as printed: አንድ ሜትር.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (2, 'D173-A1-02', 'ብትን ጨርቅ ከፖሊስተር ካኪ የተሰራ ወይም 6000 ቴትረን', 'Polyester-khaki or Tetron 6000 fabric, cut length', 'clothing', 'metre', false, true, 'fabric', 'Annex 1 (አባሪ 1) #2', 'Art. 4(2): polyester khaki is used for coat, trousers, matching shirt and trousers, jacket and straight skirt. Art. 4(7): Tetron 6000 is used for the health professionals'' full uniform and the full gown. Price-list quantity as printed: አንድ ሜትር.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (3, 'D173-A1-03', 'ሸሚዝ', 'Shirt', 'clothing', 'piece', false, true, 'clothing', 'Annex 1 (አባሪ 1) #3', 'Art. 2(9), Art. 4(3): made of fabric with lower synthetic and higher cotton content, made for shirts. Price-list quantity as printed: አንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (4, 'D173-A1-04', 'ካፖርት (ባለገበር)', 'Overcoat (with lining)', 'clothing', 'piece', false, true, 'clothing', 'Annex 1 (አባሪ 1) #4', 'Art. 2(20), Art. 6(2): wool, or cotton/synthetic with a warm lining. If unavailable, a field jacket with lining may be bought instead. Price-list quantity as printed: አንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (5, 'D173-A1-05', 'የዝናብ ልብስ', 'Rain clothing', 'clothing', 'piece', false, true, 'protective_clothing', 'Annex 1 (አባሪ 1) #5', 'Art. 2(21): rain-protection clothing of synthetic or plastic. Art. 6(3): if unavailable, an umbrella is given instead. Price-list quantity as printed: አንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (6, 'D173-A1-06', 'የፕላስቲክ ቡትስ ጫማ ባለገበር', 'Rubber/plastic boots (with lining)', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #6', 'Art. 2(15), Art. 5(7): natural-rubber boots, easy to clean, for the rainy season and mud. Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (7, 'D173-A1-07', 'ቡትስ ቆዳ ጫማ ከቆዳ የተሰራ', 'Leather boots (long)', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #7', 'Art. 2(14), Art. 5(3): laced leather boots, height not above the thigh. Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (8, 'D173-A1-08', 'አጭር ቆዳ ጫማ ከቆዳ የተሰራ', 'Short leather shoes', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #8', 'Art. 2(12), Art. 5(1): leather shoe, height not above the ankle, with or without laces. Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (9, 'D173-A1-09', 'አጭር ቡትስ ቆዳ ጫማ ከቆዳ የተሰራ', 'Short leather boots (ankle boots)', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #9', 'Art. 2(13), Art. 5(2): leather boot covering the ankle, without laces. Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (10, 'D173-A1-10', 'ሴፍቲ ቆዳ ጫማ ከቆዳ የተሰራ', 'Safety leather shoes', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #10', 'Annex 3 prints this as "ሴፍቲ ሹዝ". Art. 5(6): leather footwear protecting against falling objects, thorns and similar hazards. Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (11, 'D173-A1-11', 'የስፖርት ጫማ (ቶርሽን/ስኒከር)', 'Sports shoes (torsion / sneakers)', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #11', 'Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (12, 'D173-A1-12', 'የስፖርት ቱታ (ኮትና ሱሪ ሙሉ)', 'Sports tracksuit (full coat and trousers)', 'clothing', 'piece', false, true, 'clothing', 'Annex 1 (አባሪ 1) #12', 'Price-list quantity as printed: አንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (13, 'D173-A1-13', 'ቲሸርት', 'T-shirt', 'clothing', 'piece', false, true, 'clothing', 'Annex 1 (አባሪ 1) #13', 'Price-list quantity as printed: አንድ.', NULL, NULL);
INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (14, 'D173-A1-14', 'የባህል ጫማ', 'Traditional shoes', 'footwear', 'pair', false, true, 'footwear', 'Annex 1 (አባሪ 1) #14', 'Price-list quantity as printed: አንድ ጥንድ.', NULL, NULL);
