INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (68, 'D173-ART-02', 'የጤና ባለሙያ ሙሉ የደንብ ልብስ', 'Health professional full uniform', 'clothing', 'piece', false, true, 'clothing', 'Art. 2(17)', 'Art. 2(17): colours by unit: pale green (operating theatre and intensive care), burgundy (emergency), silver (other physicians), pale blue (nurses), pale pink (midwives). Art. 4(7): Tetron 6000. Art. 6(5): style details.', NULL, NULL);
