INSERT INTO public.ppe_items (id, code, name_am, name_en, kind, unit, immediate_eligibility, active, category, source_ref, note, unit_price, applies_to_sex) VALUES (70, 'D173-ART-04', 'ሙሉ ጋወን (አረንጓዴ)', 'Full gown, green (operating theatre and delivery)', 'clothing', 'piece', false, true, 'protective_clothing', 'Art. 2(27)', 'Art. 2(27): green full-sleeve gown worn front-to-back with ties; for surgery staff and delivery-room staff. Art. 4(7): Tetron 6000.', NULL, NULL);
