INSERT INTO public.roles (id, code, name, description, is_system) VALUES (1, 'super_admin', 'Super Admin', 'Technical owner. Everything is allowed.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (2, 'admin', 'System Admin', 'Manages accounts, roles and configuration. No access to employee records by default.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (3, 'hr_manager', 'HR Manager', 'Heads HR: all employee data, salaries, leave, recruitment, performance, separations, permanent-employment decisions.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (4, 'hr_officer', 'HR Officer', 'Day-to-day HR administration: records, leave, attendance, recruitment, training. No salaries.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (6, 'executive', 'Executive', 'Management view of the workforce and reports.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (7, 'manager', 'Line Manager', 'Manages a team: approves leave, scores appraisals, sees team attendance.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (8, 'secretary', 'Secretary', 'Office support: sees the staff directory and attendance, publishes announcements. No salaries, no sensitive IDs, no approvals.', true);
INSERT INTO public.roles (id, code, name, description, is_system) VALUES (9, 'employee', 'Employee', 'Self-service: own profile, leave, attendance and appraisal.', true);


